mapper.select:
select
, bind.id as bindId, bind.need_login, bind.call_times_pre_hour, bind.call_times_current_hour, bind.call_times_press_hour from gateway_api api left join gateway_ticket_api_bind bind on bind.api_id = api.id left join gateway_ticket ticket on ticket.id = bind.ticket_id left join gateway_app app on api.app_key = app.app_key where bind.ticket_id = #{ticket} and ticket.is_deleted = '0' and api.is_deleted = '0'
AND api.api_name LIKE #{pattern}
AND app.app_key = #{appKey}
order by api.id desc
